css:
/* ============================================
   THE HUB — Founding Day
   Theme: Warm Retail / Consumer (school cafe)
   Palette: cream, coffee brown, school green, warm gold
   ============================================ */

.hub-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #faf6f0 0%, #f0e6d2 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2c1810;
    max-width: 1200px;
    margin: 0 auto;
}

/* HEADER */
.hub-sim-container .hub-sim-header {
    background: linear-gradient(135deg, #6f4e37 0%, #4a3527 100%);
    color: #faf6f0;
    border-radius: 20px 20px 6px 6px;
    padding: 32px 36px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(74, 53, 39, 0.18);
    position: relative;
    overflow: hidden;
}
.hub-sim-container .hub-sim-header::after {
    content: "";
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, #d4a574, #2d6a4f, #d4a574);
}
.hub-sim-container .hub-sim-header-mark {
    font-size: 0.72rem;
    letter-spacing: 0.32em;
    color: #d4a574;
    font-weight: 700;
    margin-bottom: 8px;
}
.hub-sim-container .hub-sim-header h1 {
    font-size: 1.85rem;
    font-weight: 700;
    margin: 0 0 10px 0;
    color: #faf6f0;
}
.hub-sim-container .hub-sim-subtitle {
    font-size: 0.95rem;
    opacity: 0.88;
    margin: 0;
    line-height: 1.5;
    max-width: 720px;
}

/* PERIOD COUNTER */
.hub-sim-container .hub-sim-period-counter {
    background: white;
    padding: 14px 22px;
    border-radius: 12px;
    margin-bottom: 22px;
    border-left: 5px solid #2d6a4f;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
    font-size: 0.95rem;
    color: #4a3527;
}
.hub-sim-container .hub-sim-period-counter span {
    font-weight: 600;
}
.hub-sim-container .hub-sim-period-divider {
    color: #c9b896;
    margin: 0 10px;
}
.hub-sim-container .hub-sim-round-title {
    color: #2d6a4f;
}

/* STATUS CARDS */
.hub-sim-container .hub-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 26px;
}
.hub-sim-container .hub-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 4px 12px rgba(74, 53, 39, 0.08);
    border-top: 4px solid #d4a574;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.hub-sim-container .hub-sim-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(74, 53, 39, 0.14);
}
.hub-sim-container .hub-sim-status-card-cash       { border-top-color: #d4a574; }
.hub-sim-container .hub-sim-status-card-deadline   { border-top-color: #b85c38; }
.hub-sim-container .hub-sim-status-card-alignment  { border-top-color: #2d6a4f; }
.hub-sim-container .hub-sim-status-card-insight    { border-top-color: #6f4e37; }
.hub-sim-container .hub-sim-status-card-total      { border-top-color: #1b4332; background: #2d6a4f; color: #faf6f0; }
.hub-sim-container .hub-sim-status-card-total .hub-sim-label { color: #d8f3dc; }
.hub-sim-container .hub-sim-status-card-total .hub-sim-value { color: #faf6f0; }
.hub-sim-container .hub-sim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
    color: #8b6f47;
    margin-bottom: 8px;
}
.hub-sim-container .hub-sim-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #2c1810;
}

/* CONTROLS */
.hub-sim-container .hub-sim-controls {
    background: white;
    border-radius: 18px;
    padding: 28px 30px;
    margin-bottom: 24px;
    box-shadow: 0 4px 16px rgba(74, 53, 39, 0.08);
    border: 1px solid #ead8b8;
}
.hub-sim-container .hub-sim-controls h3 {
    margin: 0 0 18px 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #4a3527;
    border-bottom: 2px solid #f0e6d2;
    padding-bottom: 10px;
}
.hub-sim-container .hub-sim-brief {
    background: #fef7e6;
    border-left: 4px solid #d4a574;
    padding: 14px 18px;
    border-radius: 8px;
    font-size: 0.92rem;
    color: #4a3527;
    line-height: 1.55;
    margin-bottom: 22px;
}

/* FOUNDER GRID — ROUND 1 */
.hub-sim-container .hub-sim-founder-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 18px;
}
.hub-sim-container .hub-sim-founder-card {
    background: #fdfbf6;
    border-radius: 14px;
    padding: 22px 20px;
    border: 1px solid #ead8b8;
    text-align: center;
    transition: border-color 0.2s ease;
}
.hub-sim-container .hub-sim-founder-card:hover {
    border-color: #d4a574;
}
.hub-sim-container .hub-sim-founder-avatar {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    margin: 0 auto 10px auto;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    font-weight: 700;
    color: white;
    box-shadow: 0 4px 10px rgba(0,0,0,0.12);
}
.hub-sim-container .hub-sim-founder-maya .hub-sim-founder-avatar   { background: linear-gradient(135deg, #b85c38, #8b3a1a); }
.hub-sim-container .hub-sim-founder-daniel .hub-sim-founder-avatar { background: linear-gradient(135deg, #2d6a4f, #1b4332); }
.hub-sim-container .hub-sim-founder-aisha .hub-sim-founder-avatar  { background: linear-gradient(135deg, #6f4e37, #4a3527); }
.hub-sim-container .hub-sim-founder-name {
    font-weight: 700;
    font-size: 1.15rem;
    color: #2c1810;
    margin-bottom: 8px;
}
.hub-sim-container .hub-sim-founder-bio {
    font-size: 0.85rem;
    color: #6f5a45;
    line-height: 1.5;
    margin-bottom: 14px;
    min-height: 75px;
}
.hub-sim-container .hub-sim-founder-card label {
    display: block;
    font-size: 0.78rem;
    font-weight: 600;
    color: #4a3527;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

/* SCENARIO GRID — ROUND 2 */
.hub-sim-container .hub-sim-scenario-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 16px;
}
.hub-sim-container .hub-sim-scenario-card {
    background: #fdfbf6;
    border-radius: 14px;
    padding: 20px 22px;
    border: 1px solid #ead8b8;
    border-left-width: 6px;
}
.hub-sim-container .hub-sim-scenario-a { border-left-color: #b85c38; }
.hub-sim-container .hub-sim-scenario-b { border-left-color: #d4a574; }
.hub-sim-container .hub-sim-scenario-c { border-left-color: #2d6a4f; }
.hub-sim-container .hub-sim-scenario-tag {
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #6f4e37;
    margin-bottom: 10px;
}
.hub-sim-container .hub-sim-scenario-text {
    font-size: 0.92rem;
    color: #4a3527;
    line-height: 1.55;
    margin-bottom: 14px;
}
.hub-sim-container .hub-sim-scenario-card label {
    display: block;
    font-size: 0.78rem;
    font-weight: 600;
    color: #4a3527;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

/* FINAL GRID — ROUND 3 */
.hub-sim-container .hub-sim-final-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 18px;
}
.hub-sim-container .hub-sim-final-card {
    background: #fef7e6;
    border-radius: 14px;
    padding: 24px;
    border: 2px solid #d4a574;
}
.hub-sim-container .hub-sim-final-card label {
    display: block;
    font-size: 0.85rem;
    font-weight: 700;
    color: #4a3527;
    margin-bottom: 10px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

/* SELECTS — explicit styling on both select and option */
.hub-sim-container .hub-sim-select {
    width: 100%;
    background: #ffffff;
    color: #2c1810;
    border: 1.5px solid #c9b896;
    border-radius: 8px;
    padding: 9px 12px;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.hub-sim-container .hub-sim-select:focus {
    outline: none;
    border-color: #2d6a4f;
    box-shadow: 0 0 0 3px rgba(45, 106, 79, 0.15);
}
.hub-sim-container .hub-sim-select option {
    background: #ffffff;
    color: #2c1810;
}
.hub-sim-container .hub-sim-select-large {
    font-size: 1rem;
    padding: 12px 14px;
    font-weight: 600;
}

/* BUTTONS */
.hub-sim-container .hub-sim-button-row {
    margin-top: 22px;
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}
.hub-sim-container .hub-sim-submit-btn {
    background: linear-gradient(135deg, #2d6a4f, #1b4332);
    border: none;
    color: white;
    font-weight: 700;
    padding: 12px 28px;
    border-radius: 10px;
    font-size: 0.95rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    box-shadow: 0 4px 12px rgba(45, 106, 79, 0.3);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.hub-sim-container .hub-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 18px rgba(45, 106, 79, 0.4);
    background: linear-gradient(135deg, #2d6a4f, #1b4332);
    color: white;
}
.hub-sim-container .hub-sim-undo-btn {
    color: #6f4e37;
    border: 1.5px solid #c9b896;
    background: transparent;
    border-radius: 8px;
    padding: 8px 16px;
    font-size: 0.85rem;
}
.hub-sim-container .hub-sim-undo-btn:hover {
    background: #f0e6d2;
    color: #4a3527;
}

/* FEEDBACK CARD */
.hub-sim-container .hub-sim-feedback-card {
    background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 100%);
    color: #d8f3dc;
    border-radius: 16px;
    padding: 22px 26px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(27, 67, 50, 0.2);
    position: relative;
    overflow: hidden;
}
.hub-sim-container .hub-sim-feedback-card::before {
    content: "";
    position: absolute;
    top: 0; left: 0;
    width: 5px; height: 100%;
    background: #d4a574;
}
.hub-sim-container .hub-sim-feedback-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #d4a574;
    font-weight: 700;
    margin-bottom: 8px;
}
.hub-sim-container .hub-sim-feedback-text {
    font-size: 1rem;
    line-height: 1.55;
    color: #faf6f0;
    margin-bottom: 12px;
}
.hub-sim-container .hub-sim-feedback-meta {
    font-size: 0.85rem;
    color: #d8f3dc;
}
.hub-sim-container .hub-sim-feedback-meta strong {
    color: #d4a574;
    font-size: 1.05rem;
    margin-left: 6px;
}

/* HISTORY TABLE */
.hub-sim-container .hub-sim-history {
    background: white;
    border-radius: 14px;
    padding: 18px 22px;
    margin-bottom: 22px;
    box-shadow: 0 4px 12px rgba(74, 53, 39, 0.08);
    border: 1px solid #ead8b8;
    overflow-x: auto;
}
.hub-sim-container .hub-sim-history table {
    margin: 0;
    color: #2c1810;
}
.hub-sim-container .hub-sim-history table th {
    background: #6f4e37;
    color: #faf6f0;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border: none;
    padding: 10px 12px;
}
.hub-sim-container .hub-sim-history table td {
    padding: 10px 12px;
    border-color: #f0e6d2;
}
.hub-sim-container .hub-sim-history table tbody tr:hover {
    background: #fef7e6;
}

/* CHART */
.hub-sim-container .hub-sim-chart-card {
    background: white;
    border-radius: 16px;
    padding: 20px 24px;
    box-shadow: 0 4px 16px rgba(74, 53, 39, 0.08);
    border: 1px solid #ead8b8;
    height: 320px;
}

/* RESPONSIVE */
@media (max-width: 768px) {
    .hub-sim-container {
        padding: 16px;
    }
    .hub-sim-container .hub-sim-header {
        padding: 22px 20px;
    }
    .hub-sim-container .hub-sim-header h1 {
        font-size: 1.4rem;
    }
    .hub-sim-container .hub-sim-controls {
        padding: 18px 16px;
    }
    .hub-sim-container .hub-sim-founder-grid,
    .hub-sim-container .hub-sim-final-grid {
        grid-template-columns: 1fr;
    }
    .hub-sim-container .hub-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .hub-sim-container .hub-sim-value {
        font-size: 1.3rem;
    }
}

